<script setup>
defineProps({ result: { type: Object, required: true }, query: { type: Object, default: () => ({}) }, topicLabel: { type: String, default: '议题' } })
defineEmits(['navigate', 'query'])
</script>
<template><h3 v-if="result.contextTopic" class="theme-discussion-title">{{ result.contextTopic.title }}</h3><p v-if="!result.value.length" class="theme-empty">当前议题暂无讨论。</p><div class="theme-timeline"><article v-for="item in result.value" :key="item.id"><small>{{ item.author_name }} · {{ item.created_at.slice(0, 10) }}</small><p>{{ item.content }}</p></article></div><button v-if="result.contextTopic" class="theme-link" :data-object-key="`topic:${result.contextTopic.id}`" @click="$emit('navigate', { kind: 'object', objectType: 'topic', id: result.contextTopic.id })">查看{{ topicLabel }}详情与完整上下文 →</button><div v-if="result.pagination && (result.pagination.total > result.pagination.limit || result.pagination.offset > 0)" class="theme-toolbar"><span>共 {{ result.pagination.total }} 条讨论 · 最新在前</span><button :disabled="result.pagination.offset === 0" @click="$emit('query', { ...query, offset: Math.max(0, result.pagination.offset - result.pagination.limit) })">上一页</button><button :disabled="result.pagination.offset + result.pagination.limit >= result.pagination.total" @click="$emit('query', { ...query, offset: result.pagination.offset + result.pagination.limit })">下一页</button></div></template>
